const first = await tools.list_issues({ repo: "acme/api", state: "open", page: 1 });
const arr = (x: any): any[] => Array.isArray(x) ? x : (x?.items ?? x?.issues ?? x?.data ?? []);
let all: any[] = [...arr(first)];
for (let p = 2; p <= 200; p++) {
  const r = arr(await tools.list_issues({ repo: "acme/api", state: "open", page: p }));
  if (r.length === 0) break;
  all.push(...r);
}
const sorted = [...all].sort((a, b) => a.number - b.number);
const hasMs = (i: any) => i.milestone !== undefined && i.milestone !== null;
const sample = sorted.slice(0, 3).map(i => ({ number: i.number, title: i.title, milestone: i.milestone ?? null, keys: Object.keys(i) }));
const results: any[] = [];
for (const i of sorted) {
  if (hasMs(i)) { if (i.milestone === undefined) {} ; }
  const d: any = await tools.get_issue({ repo: "acme/api", number: i.number });
  const ms = d?.milestone ?? null;
  results.push({ number: i.number, title: d?.title ?? i.title, milestone: ms, state: d?.state ?? i.state });
  if (!ms) break;
}
return { total: all.length, sample, last: results[results.length - 1], checked: results.length };
